import re, collections

def parse_pair(txt, n):
    pat=rf'Demo pair {n} input \(\d+x\d+\):\n(.*?)\nDemo pair {n} output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance\.|\Z)'
    m=re.search(pat,txt,re.S)
    if not m: raise ValueError('no match')
    def grid(s): return [[int(x) for x in line.split()] for line in s.strip().splitlines()]
    return grid(m.group(1)),grid(m.group(2))
