def transform_comp(grid):
    H,W=len(grid),len(grid[0]); bg=collections.Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); out=[[bg]*W for _ in range(H)]
    for r in range(H):
      for c in range(W):
       col=grid[r][c]
       if col==bg or (r,c) in seen: continue
       stack=[(r,c)]; seen.add((r,c)); cells=[]
       while stack:
        y,x=stack.pop(); cells.append((y,x))
        for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
         if 0<=yy<H and 0<=xx<W and (yy,xx) not in seen and grid[yy][xx]==col:
          seen.add((yy,xx)); stack.append((yy,xx))
       rs=[y for y,x in cells]; cs=[x for y,x in cells]
       r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
       area=(r1-r0+1)*(c1-c0+1)
       if r1>r0 and c1>c0 and len(cells)>=3 and len(cells)/area>=0.4:
        for y in range(r0,r1+1):
         for x in range(c0,c1+1): out[y][x]=col
    return out
